    setWindowTitle("Exportar modelo 3D");setObjectName("exportModelDialog");resize(640,760);pool_.setMaxThreadCount(1);auto *layout=new QVBoxLayout(this);settings_=new QWidget;auto *settingsLayout=new QVBoxLayout(settings_);settingsLayout->setContentsMargins(0,0,0,0);auto *scroll=new QScrollArea;scroll->setWidgetResizable(true);scroll->setFrameShape(QFrame::NoFrame);scroll->setWidget(settings_);layout->addWidget(scroll,1);
    auto *form=new QFormLayout;settingsLayout->addLayout(form);format_=new QComboBox;format_->setObjectName("exportFormat");format_->addItems({"GLB · glTF 2.0 (archivo único)","OBJ · geometría de intercambio","STL · superficie triangulada"});format_->setItemData(0,int(ModelFormat::Glb));format_->setItemData(1,int(ModelFormat::Obj));format_->setItemData(2,int(ModelFormat::Stl));form->addRow("Formato",format_);
