    auto *transform=new QFormLayout;settingsLayout->addLayout(transform);scale_=new QDoubleSpinBox;scale_->setObjectName("exportScale");scale_->setDecimals(6);scale_->setRange(.000001,1000000);scale_->setValue(1);transform->addRow("Escala uniforme",scale_);axes_=new QComboBox;axes_->setObjectName("exportAxes");axes_->addItems({"XYZ","XZY","YXZ","YZX","ZXY","ZYX"});transform->addRow("XYZ de salida toma los ejes",axes_);
