    reverse_=new QCheckBox("Invertir orientación de caras y normales");reverse_->setObjectName("exportReverseFaces");transform->addRow(reverse_);normals_=new QComboBox;normals_->setObjectName("exportNormals");normals_->addItems({"Conservar (normalizadas)","Recalcular desde las caras","No exportar"});transform->addRow("Normales",normals_);
