ExportDialog::~ExportDialog(){if(progress_)progress_->cancel=true;watcher_.waitForFinished();}
void ExportDialog::reject(){if(watcher_.isRunning()){progress_->cancel=true;status_->setText("Cancelando exportación…");return;}QDialog::reject();}
QVector<ExportMesh> ExportDialog::selectedMeshes()const{QVector<ExportMesh> result;for(int i=0;i<entries_.size();++i)if(meshes_->topLevelItem(i)->checkState(0)==Qt::Checked){const auto &e=entries_[i];result.append({e.name,e.source,e.data});}return result;}
ModelExportOptions ExportDialog::options()const{ModelExportOptions o;o.format=ModelFormat(format_->currentData().toInt());o.scale=scale_->value();for(int i=0;i<3;++i){o.axes[i]=QString("XYZ").indexOf(axes_->currentText()[i]);o.negate[i]=negate_[i]->isChecked();}o.uvs=uvs_->isChecked();o.flipV=flipV_->isChecked();o.reverseFaces=reverse_->isChecked();o.normals=ExportNormals(normals_->currentIndex());o.material=o.format==ModelFormat::Glb&&material_->isChecked();o.doubleSided=doubleSided_->isChecked();o.color=color_;o.protectedPaths=protectedPaths_;return o;}
void ExportDialog::refresh(){
    auto o=options();bool stl=o.format==ModelFormat::Stl,glb=o.format==ModelFormat::Glb;uvs_->setEnabled(!stl);flipV_->setEnabled(!stl&&uvs_->isChecked());normals_->setEnabled(!stl);material_->setEnabled(glb);colorButton_->setEnabled(glb&&material_->isChecked());doubleSided_->setEnabled(glb&&material_->isChecked());auto selected=selectedMeshes();int stale=0,noUvs=0;for(int i=0;i<entries_.size();++i)if(meshes_->topLevelItem(i)->checkState(0)==Qt::Checked){stale+=entries_[i].stale;noUvs+=!entries_[i].data->hasUvs;}
    QString description=stl?"STL: exporta triángulos y normales de cara. Une las mallas en una superficie; pierde nombres, UV, normales de vértice y materiales.":glb?"GLB: conserva mallas separadas, nombres, posiciones, caras y, si se activan, normales, UV y un material mate de color.":"OBJ: conserva objetos separados, nombres, posiciones, caras y, si se activan, normales y UV. Este exportador no genera materiales MTL.";
    description+=QString("\n%1 mallas seleccionadas. XYZ de salida = %2 de entrada × %3; se aplican los signos elegidos.").arg(selected.size()).arg(axes_->currentText()).arg(o.scale);
    description+="\nSe exportan las coordenadas reales, sin el encuadre del visor. Las reflexiones corrigen automáticamente el orden de las caras. No se reduce la geometría.";
    description+=glb?"\nGLB interpreta las distancias en metros y Y arriba; ajusta escala y ejes a tu binario.":"\nOBJ/STL no definen unidades físicas: acuerda la escala con el programa de destino.";
    description+="\nEn esta versión no se exportan texturas, huesos, animaciones, gradientes de depuración, offsets ni reglas del binario.";
    if(stale)description+=QString("\nAviso: %1 mallas son capturas anteriores del documento.").arg(stale);if(noUvs&&!stl&&o.uvs)description+=QString("\n%1 mallas no tienen UV: se exportarán sin UV.").arg(noUvs);summary_->setText(description);save_->setEnabled(!selected.isEmpty()&&!watcher_.isRunning());
}
void ExportDialog::startExport(const QString &path){if(watcher_.isRunning())return;auto meshes=selectedMeshes();if(meshes.isEmpty()){status_->setText("Selecciona al menos una malla.");return;}auto o=options();progress_=std::make_shared<ExportProgress>();auto progress=progress_;settings_->setEnabled(false);save_->setEnabled(false);progressBar_->setValue(0);progressBar_->show();status_->setText("Exportando una captura de las mallas seleccionadas…");watcher_.setFuture(QtConcurrent::run(&pool_,[path,meshes,o,progress]{return exportModel(path,meshes,o,progress);}));}
